<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\SchoolAsset; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class AssetController extends Controller { public function index(Request $request){$q=SchoolAsset::query()->when($request->filled('q'),fn($q)=>$q->where(fn($q)=>$q->where('name','like','%'.$request->q.'%')->orWhere('code','like','%'.$request->q.'%')))->orderBy('name');return view('admin.assets.index',['assets'=>$q->get()]);} public function store(Request $r){SchoolAsset::create($this->data($r));return back()->with('success','Aset ditambahkan.');} public function update(Request $r,SchoolAsset $asset){$asset->update($this->data($r,$asset));return back()->with('success','Aset diperbarui.');} public function destroy(SchoolAsset $asset){$asset->delete();return back()->with('success','Aset dihapus.');} private function data(Request $r,?SchoolAsset $asset=null):array{return $r->validate(['code'=>['required','string','max:50',Rule::unique('school_assets','code')->ignore($asset)],'name'=>['required','string','max:150'],'category'=>['nullable','string','max:100'],'location'=>['nullable','string','max:100'],'quantity'=>['required','integer','min:0'],'condition'=>['required',Rule::in(array_keys(SchoolAsset::CONDITIONS))],'status'=>['required',Rule::in(array_keys(SchoolAsset::STATUSES))],'acquired_on'=>['nullable','date'],'acquisition_value'=>['nullable','numeric','min:0'],'note'=>['nullable','string','max:2000']]);} }
